package com.yeyamo_mobile.api.discovery_service.application.maps;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.Map;import org.junit.jupiter.api.Test;import com.yeyamo_mobile.api.discovery_service.application.port.ExternalMapsPort;import com.yeyamo_mobile.api.discovery_service.infrastructure.maps.ExternalMapsException;import org.springframework.http.HttpStatus;
class MapsServiceTest{@Test void geocodesAddress(){var port=mock(ExternalMapsPort.class);var expected=new GeocodeResult("Bastos, Yaoundé",3.9,11.5,"place-1",Map.of("locality","Yaoundé"));when(port.geocode("Bastos")).thenReturn(expected);assertEquals(expected,new MapsService(port).geocode(" Bastos "));}@Test void propagatesNotFound(){var port=mock(ExternalMapsPort.class);when(port.geocode("unknown")).thenThrow(new ExternalMapsException("LOCATION_NOT_FOUND","Adresse introuvable",HttpStatus.NOT_FOUND));var error=assertThrows(ExternalMapsException.class,()->new MapsService(port).geocode("unknown"));assertEquals("LOCATION_NOT_FOUND",error.code());}@Test void reverseGeocodesCoordinates(){var port=mock(ExternalMapsPort.class);var coordinate=new Coordinate(3.848,11.5021);var expected=new GeocodeResult("Yaoundé",coordinate.latitude(),coordinate.longitude(),"p",Map.of());when(port.reverseGeocode(coordinate)).thenReturn(expected);assertEquals(expected,new MapsService(port).reverse(coordinate.latitude(),coordinate.longitude()));}@Test void calculatesDrivingRoute(){var port=mock(ExternalMapsPort.class);var origin=new Coordinate(3.8,11.5);var destination=new Coordinate(3.9,11.6);var expected=new RouteResult(12000,1800,"encoded",origin,destination);when(port.route(origin,destination,TravelMode.DRIVE)).thenReturn(expected);assertEquals(expected,new MapsService(port).route(origin,destination,TravelMode.DRIVE));}}
